package io.github.iutils.welcome.domain;

import java.util.Objects;

/**
 * Represents a welcome message generated by the domain rules for a specific player.
 *
 * @param player       the target player receiving the welcome
 * @param template     the original configured template before placeholder substitution
 * @param renderedText the text after substituting domain placeholders such as {@code {player}}
 * @param usePrefix    whether the plugin prefix should be included when presenting the message
 */
public record WelcomeMessage(
        WelcomePlayer player,
        String template,
        String renderedText,
        boolean usePrefix
) {

    public WelcomeMessage {
        Objects.requireNonNull(player, "WelcomePlayer cannot be null");
        Objects.requireNonNull(template, "Template cannot be null");
        Objects.requireNonNull(renderedText, "RenderedText cannot be null");
    }
}
